import { z } from "zod";

// Never trust input from the browser. Zod checks shape + limits and gives us
// typed data back. Limits stop someone posting a 5MB "title".

// Visitor IDs are generated by the widget (crypto.randomUUID()).
export const visitorIdSchema = z.string().min(8).max(64);

export const createFeedbackSchema = z.object({
  visitorId: visitorIdSchema,
  title: z.string().trim().min(3, "Title is too short").max(120),
  description: z.string().trim().max(2000).optional(),
  pageUrl: z.string().url().max(2048).optional(),
});

export const voteSchema = z.object({
  visitorId: visitorIdSchema,
});
